@page "/dashboard"
@using sv_bcba49d2dc9a457a936c9dc59a0995ce.Services
@inject WarehouseState WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>
<h4>Current site: @WarehouseState.SelectedWarehouseName</h4>

<div class="card mt-3" style="max-width: 400px;">
    <div class="card-body">
        <h5 class="card-title">Low-Stock Alerts</h5>
        <p class="card-text">
            Items below minimum level:
            <span class="badge bg-danger fs-5">@AlertService.CurrentLowStockCount</span>
        </p>
        <p class="text-muted small">Auto-refreshes every 10 seconds while this page is open.</p>
    </div>
</div>

@code {
    private Action? _alertHandler;
    private Action? _warehouseHandler;

    protected override void OnInitialized()
    {
        // Subscribe to alert data changes
        _alertHandler = () => InvokeAsync(StateHasChanged);
        AlertService.OnAlertDataChanged += _alertHandler;

        // Subscribe to warehouse selection changes
        _warehouseHandler = () => InvokeAsync(StateHasChanged);
        WarehouseState.OnChange += _warehouseHandler;

        // Start polling while this page is visible
        AlertService.StartPolling();
    }

    public void Dispose()
    {
        AlertService.StopPolling();

        if (_alertHandler is not null)
            AlertService.OnAlertDataChanged -= _alertHandler;
        if (_warehouseHandler is not null)
            WarehouseState.OnChange -= _warehouseHandler;
    }
}

